:root {
  color-scheme: dark;
  --br-bg-deep: #060a12;
  --br-bg-panel: rgba(15, 23, 42, 0.86);
  --br-gold: #f59e0b;
  --br-gold-bright: #fde047;
  --br-cyan: #38bdf8;
  --br-emerald: #22c55e;
  --br-crimson: #ef4444;
  --br-text-main: #f8fafc;
  --br-text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  background: var(--br-bg-deep);
  color: var(--br-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC",
    "Microsoft YaHei", sans-serif;
  overflow-x: hidden;
  user-select: none;
}

/* Full-Bleed Tactical Command Center Container (Zero Vertical Shift) */
.br-app {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 10px 16px 14px;
  gap: 10px;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(17, 28, 45, 0.92) 0%,
      rgba(8, 13, 24, 0.98) 68%,
      #04070d 100%
    ),
    repeating-linear-gradient(
      0deg,
      rgba(56, 189, 248, 0.018) 0px,
      rgba(56, 189, 248, 0.018) 1px,
      transparent 1px,
      transparent 24px
