  overflow: hidden;
}

/* Top Bar */
.br-topbar {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 14px;
  border-radius: 12px;
  background: rgba(7, 11, 20, 0.88);
  border: 1px solid rgba(245, 158, 11, 0.25);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(12px);
  flex-wrap: wrap;
  flex-shrink: 0;
}

.br-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.br-emblem {
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-brand h1 {
  font-size: 16.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  background: linear-gradient(135deg, #fef08a 0%, #f59e0b 65%, #fbbf24 100%);
