  color: rgba(148, 163, 184, 0.45);
}

/* K.I.A Eliminated Stamp */
.br-kia-stamp {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 8;
  padding: 2px 8px;
  border: 2px solid #ef4444;
  border-radius: 5px;
  background: rgba(69, 10, 10, 0.92);
  color: #fca5a5;
  font-size: 10.5px;
