  transform: rotate(-12deg);
  animation: brStampSlam 0.34s cubic-bezier(0.18, 0.89, 0.32, 1.28);
}

.br-kia-stamp span::before {
  content: attr(data-stamp);
}

@keyframes brStampSlam {
  0% {
    opacity: 0;
    transform: rotate(-26deg) scale(2.2);
  }
  100% {
    opacity: 1;
    transform: rotate(-12deg) scale(1);
  }
}

/* Center Stage: Ticker + 8x6 Tactical Grid + Control Dock */
/* Center Stage: Direct Clean Stage for 8x8 Tactical Sandtable (No redundant nested boxes) */
.br-center-stage {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  container-type: size;
}

.br-welcome-overlay {
  position: absolute;
  inset: 0;
  z-index: 25;
  background: rgba(6, 10, 18, 0.86);
  backdrop-filter: blur(6px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
  padding: 20px;
}

.br-welcome-overlay h2 {
  font-size: 19px;
  font-weight: 800;
  color: #fde047;
}

.br-welcome-overlay p {
  max-width: 460px;
  font-size: 13px;
  line-height: 1.55;
  color: #cbd5e1;
}

.br-cta-btn {
  margin-top: 6px;
