  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  color: #fffbeb;
  font-size: 13.5px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
}

/* 8x8 Tactical Sandtable (Directly occupies entire central arena, fully maximized) */
.br-board-box {
  --tile-size: clamp(34px, min(calc((100cqw - 24px) / 8), calc((100cqh - 24px) / 8)), 110px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: auto;
}

.br-winner-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 9px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.22);
  border: 1px solid #fde047;
  color: #fde047;
  font-size: 11px;
  font-weight: 800;
  box-shadow: 0 0 10px rgba(250, 204, 21, 0.35);
}

.br-turn-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.5);
  color: #7dd3fc;
  font-size: 11px;
  font-weight: 700;
}

.br-col-headers {
  display: grid;
  grid-template-columns: 20px repeat(8, var(--tile-size));
  gap: 2px;
  margin-bottom: 3px;
  flex-shrink: 0;
}

.br-corner-spacer {
  width: 20px;
}

.br-col-label {
  width: var(--tile-size);
  text-align: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
  line-height: 16px;
}

.br-grid-body {
  display: grid;
  grid-template-columns: 20px calc(8 * var(--tile-size) + 7 * 2px);
  gap: 2px;
  align-items: center;
}

.br-row-headers {
  display: grid;
  grid-template-rows: repeat(8, var(--tile-size));
  gap: 2px;
  height: calc(8 * var(--tile-size) + 7 * 2px);
}

.br-row-label {
  height: var(--tile-size);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
}

/* Seamless 8x8 Tactical Sandtable (Integrative Tabletop, Low Grid Clutter) */
.br-tiles-grid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(8, var(--tile-size));
  grid-template-rows: repeat(8, var(--tile-size));
  gap: 2px;
  width: calc(8 * var(--tile-size) + 7 * 2px);
  height: calc(8 * var(--tile-size) + 7 * 2px);
  background: #090e18;
  border-radius: 8px;
  border: 1px solid rgba(56, 189, 248, 0.22);
  box-shadow:
    inset 0 0 32px rgba(0, 0, 0, 0.8),
    0 10px 28px rgba(0, 0, 0, 0.6);
}

/* SVG Bullet Tracer & Explosion Ring */
.br-tracer-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
}

.br-tracer-line {
  stroke-width: 0.9;
  stroke-linecap: round;
  animation: brTracerFade 0.95s ease-out forwards;
}

.br-tracer-line.is-bullet {
  stroke: #fde047;
  filter: drop-shadow(0 0 4px #f59e0b);
}

.br-tracer-line.is-grenade {
  stroke: #ef4444;
  stroke-dasharray: 2 1.5;
  filter: drop-shadow(0 0 5px #ef4444);
}

.br-impact-ring {
  fill: rgba(239, 68, 68, 0.35);
  stroke: #fde047;
  stroke-width: 0.6;
  animation: brImpactPulse 0.85s ease-out forwards;
}

@keyframes brTracerFade {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

@keyframes brImpactPulse {
  0% {
    transform: scale(0.5);
    transform-origin: center;
    opacity: 1;
  }
  100% {
    transform: scale(1.8);
    transform-origin: center;
    opacity: 0;
  }
}

/* Individual Tile: Seamless Terrain Zone (No bulky cards, zero coordinate clutter) */
.br-tile {
  width: var(--tile-size);
  height: var(--tile-size);
  box-sizing: border-box;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 3px;
  border-radius: 4px;
  border: 1px solid rgba(148, 163, 184, 0.05);
  background: rgba(18, 27, 43, 0.38);
  color: #f8fafc;
  cursor: pointer;
  overflow: hidden;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.br-tile:hover {
  background: rgba(56, 189, 248, 0.1);
  border-color: rgba(56, 189, 248, 0.35);
}

/* Safe Zone */
.br-tile.is-safe {
  background: rgba(22, 33, 51, 0.45);
  border-color: rgba(148, 163, 184, 0.07);
}

/* Terrain Subtle Textures */
.br-tile.is-ter-base {
  background: radial-gradient(circle, rgba(180, 83, 9, 0.35) 0%, rgba(120, 53, 15, 0.22) 100%);
  border-color: rgba(245, 158, 11, 0.28);
}
.br-tile.is-ter-tower {
  background: radial-gradient(circle, rgba(14, 116, 144, 0.35) 0%, rgba(8, 51, 68, 0.25) 100%);
  border-color: rgba(56, 189, 248, 0.28);
}
.br-tile.is-ter-bush {
  background: #064e3b;
  border-color: rgba(34, 197, 94, 0.3);
}
.br-tile.is-ter-bunker {
  background: rgba(30, 41, 59, 0.65);
  border-color: rgba(148, 163, 184, 0.3);
}

/* Electromagnetic Storm (Continuous Deep Radiation Veil across battlefield) */
.br-tile.is-storm {
  background: rgba(59, 7, 100, 0.38);
  border-color: rgba(147, 51, 234, 0.14);
  filter: saturate(0.55) brightness(0.68);
}

/* Storm Center Beacon */
.br-tile.is-storm-center {
  background: rgba(245, 158, 11, 0.16);
  border-color: rgba(251, 191, 36, 0.55);
  box-shadow: 0 0 14px rgba(245, 158, 11, 0.25);
}

/* Fog of War Shroud */
.br-tile.is-fog {
  opacity: 0.5;
  filter: brightness(0.7);
}

/* Interactive Move & Attack Highlights */
.br-tile.is-move-target {
  border-color: #38bdf8;
  box-shadow:
    inset 0 0 14px rgba(56, 189, 248, 0.28),
    0 0 10px rgba(56, 189, 248, 0.25);
}

.br-tile.is-move-target:hover {
  transform: scale(1.02);
  border-color: #7dd3fc;
}

.br-tile.is-attack-target {
  border-color: #ef4444;
  box-shadow:
    0 0 12px rgba(239, 68, 68, 0.55),
    inset 0 0 16px rgba(220, 38, 38, 0.42);
}

.br-tile.is-attack-target:hover {
  transform: scale(1.03);
}

.br-tile-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  line-height: 1;
}

/* Interactive Sandtable Terrain Micro-Landscape (Layer 1 Background) */
.br-tile-terrain-art {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  overflow: hidden;
}

.br-terrain-svg {
  width: 100%;
  height: 100%;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.br-terrain-svg.is-bush {
  opacity: 0.9;
  filter: drop-shadow(0 2px 5px rgba(5, 46, 22, 0.6));
}

.br-terrain-svg.is-bunker {
  opacity: 0.88;
  filter: drop-shadow(0 2px 6px rgba(15, 23, 42, 0.7));
}

.br-terrain-svg.is-tower {
  opacity: 0.85;
}

.br-terrain-svg.is-base {
  opacity: 0.85;
}

/* Storm Center Beacon */
.br-storm-center-marker {
  position: absolute;
  top: 3px;
  left: 3px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-beacon-art {
  width: 16px;
  height: 16px;
  animation: brCenterBeaconPulse 1.4s ease-in-out infinite alternate;
}

/* Sonar Ping Radar Ring */
.br-sonar-svg {
  width: 26px;
  height: 26px;
}

.br-sonar-ripple {
  animation: brSonarWave 1.2s ease-out infinite;
  transform-origin: center;
}

/* Combat Clash Badge */
.br-cqb-clash-badge {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: brClashShake 0.6s ease-in-out infinite alternate;
  pointer-events: none;
}

.br-clash-svg {
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 0 6px #ef4444);
}

/* Tactical Token States inside Terrain */
.br-board-token.is-in-bush .br-token-disc {
  box-shadow:
    0 0 0 2px rgba(34, 197, 94, 0.45),
    0 4px 10px rgba(5, 46, 22, 0.7);
}

.br-board-token.is-in-bunker .br-token-disc {
  box-shadow:
    0 0 0 2px rgba(148, 163, 184, 0.5),
    0 4px 12px rgba(0, 0, 0, 0.8);
}

@keyframes brCenterBeaconPulse {
  from {
    transform: scale(0.95);
    filter: drop-shadow(0 0 2px #f59e0b);
  }
  to {
    transform: scale(1.2);
    filter: drop-shadow(0 0 8px #fde047);
  }
}

/* Holographic Safe Zone Forcefield & Ballistics FX Layer */
.br-board-fx-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 4;
}

.br-storm-forcefield {
  fill: none;
  stroke: rgba(56, 189, 248, 0.65);
  stroke-width: 0.65;
  stroke-dasharray: 2.5 1.5;
  filter: drop-shadow(0 0 5px rgba(56, 189, 248, 0.6));
  animation: brForcefieldRotate 18s linear infinite;
  transform-origin: center;
}

@keyframes brForcefieldRotate {
  from {
    stroke-dashoffset: 0;
  }
  to {
    stroke-dashoffset: 40;
  }
}

/* Tactical Crates Presentation (Pure Micro-models, Zero text noise) */
.br-loot-box {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.br-loot-box.is-prominent {
  margin: auto;
}

.br-loot-box.is-compact {
  position: absolute;
  top: 3px;
  right: 3px;
  transform-origin: top right;
  transform: scale(0.85);
}

.br-loot-box:hover {
  transform: translateY(-2px) scale(1.08);
}

.br-loot-box-art {
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.6));
}

.br-loot-box.is-airdrop .br-loot-box-art {
  animation: brAirdropHover 1.6s ease-in-out infinite alternate;
}

@keyframes brAirdropHover {
  from {
    transform: translateY(0);
    filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.6)) drop-shadow(0 0 6px rgba(250, 204, 21, 0.35));
  }
  to {
    transform: translateY(-2px);
    filter: drop-shadow(0 5px 10px rgba(0, 0, 0, 0.7)) drop-shadow(0 0 10px rgba(250, 204, 21, 0.65));
  }
}

.br-airdrop-beacon {
  animation: brAirdropBeaconPulse 1s ease-in-out infinite alternate;
}

@keyframes brAirdropBeaconPulse {
  from {
    opacity: 0.3;
    r: 2.5;
  }
  to {
    opacity: 1;
    r: 4.5;
  }
}

/* Sonar Ping Blip */
.br-ping-sonar {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: auto;
}

.br-sonar-ring {
  position: absolute;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1.5px solid #ef4444;
  animation: brSonarWave 1.2s ease-out infinite;
}

@keyframes brSonarWave {
  0% {
    transform: scale(0.4);
    opacity: 1;
  }
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}

.br-sonar-core {
  font-size: 13px;
  position: relative;
  z-index: 2;
}

/* Tactical Agent Piece on Board */
.br-tile-agents {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  min-height: 0;
}

.br-tile-agents.count-2 {
  gap: 3px;
}

.br-board-token {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.15s ease;
}

.br-board-token:hover {
  transform: translateY(-2px) scale(1.06);
}

.br-board-token.is-active-turn {
  z-index: 6;
}

/* Turn Ping Radar Ring */
.br-token-ping-ring {
  position: absolute;
  inset: -5px;
  width: calc(100% + 10px);
  height: calc(100% + 10px);
  border-radius: 50%;
  border: 1.5px solid #fbbf24;
  animation: brTokenRadarSpin 1.8s ease-out infinite;
  pointer-events: none;
}

@keyframes brTokenRadarSpin {
  0% {
    transform: scale(0.75);
    opacity: 1;
  }
  100% {
    transform: scale(1.35);
    opacity: 0;
  }
}

/* Guarding Holo Shield & Forcefield Perimeter */
.br-token-guard-aura {
  position: absolute;
  top: -7px;
  right: -5px;
  z-index: 7;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.95);
  border: 1.2px solid #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #38bdf8;
  animation: brGuardPulse 1.8s ease-in-out infinite alternate;
}

@keyframes brGuardPulse {
  from {
    transform: scale(1);
    box-shadow: 0 0 6px rgba(56, 189, 248, 0.6);
  }
  to {
    transform: scale(1.15);
    box-shadow: 0 0 12px rgba(56, 189, 248, 0.95);
  }
}

.br-board-token.is-guarding .br-token-disc::before {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1.5px dashed #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.5);
  animation: brForcefieldRotate 10s linear infinite;
  pointer-events: none;
}

/* Token Avatar Disc */
.br-token-disc {
  position: relative;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid #38bdf8;
  background: #0f172a;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.count-2 .br-token-disc {
  width: 28px;
  height: 28px;
}

.br-token-seat-badge {
  position: absolute;
  top: -3px;
  left: -4px;
  z-index: 5;
  padding: 0 3.5px;
  border-radius: 4px;
  color: #0f172a;
  font-size: 8.5px;
  font-weight: 900;
  line-height: 12px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
}

/* Weapon Stance Tag */
.br-token-weapon-badge {
  position: relative;
  z-index: 5;
  margin-top: -4px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(15, 23, 42, 0.95);
  border: 1px solid rgba(148, 163, 184, 0.4);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.5);
  white-space: nowrap;
}

.br-token-weapon-badge.is-awm,
.br-token-weapon-badge.is-sniper {
  border-color: #f59e0b;
  box-shadow: 0 0 6px rgba(245, 158, 11, 0.4);
}

.br-token-weapon-badge.is-rifle {
  border-color: #38bdf8;
}

.br-token-weapon-badge.is-shotgun {
  border-color: #ef4444;
}

.br-token-wep-code {
  font-size: 8.5px;
  font-weight: 800;
  color: #fde047;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.br-token-ammo-text {
  font-size: 8px;
  font-weight: 800;
  color: #94a3b8;
}

.br-token-ammo-text.is-empty {
  color: #f87171;
}

.count-2 .br-token-weapon-badge {
  transform: scale(0.9);
  margin-top: -3px;
}

/* Direct HP Gauge on Token for Immediate Battlefield Readability */
.br-token-hp-gauge {
  position: relative;
  z-index: 5;
  width: 26px;
  height: 3.5px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.88);
  border: 0.5px solid rgba(255, 255, 255, 0.2);
  margin-top: -2px;
  overflow: hidden;
}

.br-token-hp-fill {
  height: 100%;
  background: #22c55e;
  border-radius: 999px;
  transition: width 0.2s ease;
}

.br-token-hp-fill.is-warn {
  background: #f59e0b;
}

.br-token-hp-fill.is-critical {
  background: #ef4444;
}

.count-2 .br-token-hp-gauge {
  width: 20px;
  height: 3px;
}

.br-floating-dmg {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 20;
  padding: 1px 5px;
  border-radius: 5px;
  background: #dc2626;
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  animation: brFloatUp 0.95s ease-out forwards;
}

@keyframes brFloatUp {
  0% {
    opacity: 1;
    transform: translateY(4px) scale(1.2);
  }
  100% {
    opacity: 0;
    transform: translateY(-12px) scale(0.95);
  }
}

/* Floating Action HUD (Non-intrusive floating pill, zero arena compression) */
.br-floating-hud {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 35;
  max-width: 95%;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(11, 17, 32, 0.94);
  backdrop-filter: blur(14px);
  border: 1.5px solid rgba(245, 158, 11, 0.55);
  box-shadow:
    0 8px 30px rgba(0, 0, 0, 0.8),
    0 0 16px rgba(245, 158, 11, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: brHudPop 0.25s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes brHudPop {
  from {
    opacity: 0;
    transform: translate(-50%, 8px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }
}

.br-hud-inner {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: nowrap;
}

.br-hud-prompt {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #fde047;
  white-space: nowrap;
}

.br-beacon-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fde047;
  box-shadow: 0 0 8px #f59e0b;
  flex-shrink: 0;
}

.br-combat-actions-row,
.br-radio-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.br-ap-badge {
  font-size: 11.5px;
  font-weight: 800;
  padding: 4px 9px;
  border-radius: 7px;
  background: rgba(245, 158, 11, 0.2);
  border: 1px solid #fbbf24;
  color: #fde047;
}

.br-act-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 32px;
  padding: 0 11px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(30, 41, 59, 0.85);
  color: #f8fafc;
}

.br-act-btn.is-loot {
  border-color: rgba(245, 158, 11, 0.5);
  color: #fde047;
}

.br-act-btn.is-heal {
  border-color: rgba(34, 197, 94, 0.5);
  color: #86efac;
}

.br-act-btn.is-grenade {
  border-color: rgba(239, 68, 68, 0.5);
  color: #fca5a5;
}

.br-act-btn.is-grenade.is-selected {
  background: #dc2626;
  color: #ffffff;
}

.br-act-btn.is-guard {
  border-color: rgba(56, 189, 248, 0.5);
  color: #7dd3fc;
}

.br-act-btn.is-gold {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
}

.br-act-btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.br-radio-input {
  flex: 1;
  min-width: 160px;
  height: 32px;
  padding: 0 11px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(7, 11, 20, 0.85);
  color: #f8fafc;
  font-size: 12px;
  outline: none;
}

.br-radio-input:focus {
  border-color: #fbbf24;
}

/* Modal & Fixed-Position Custom Dropdowns */
.br-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(5, 8, 17, 0.8);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.br-modal-card {
  width: 100%;
  max-width: 640px;
  border-radius: 18px;
  background: #0f172a;
  border: 1px solid rgba(245, 158, 11, 0.38);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.65);
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}

.br-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.br-modal-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.br-modal-title-row h3 {
  font-size: 16px;
  font-weight: 800;
  color: #fde047;
}

.br-modal-close {
  background: transparent;
  border: none;
  color: #94a3b8;
  cursor: pointer;
}

.br-modal-body {
  padding: 16px 18px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.br-config-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.br-config-label {
  font-size: 12px;
  font-weight: 700;
  color: #94a3b8;
}

.br-mode-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.br-mode-tab {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(30, 41, 59, 0.6);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.br-mode-tab.is-active {
  background: rgba(245, 158, 11, 0.2);
  border-color: #fbbf24;
  color: #fde047;
}

.br-seats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.br-seat-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.br-seat-field-label {
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
}

.br-select-wrap {
  position: relative;
}

.br-select-trigger {
  width: 100%;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(30, 41, 59, 0.75);
  color: #f8fafc;
  cursor: pointer;
}

.br-select-item-left {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
}

.br-select-icon {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.br-select-icon.is-human {
  background: rgba(245, 158, 11, 0.2);
  color: #fde047;
}
.br-select-icon.is-bot {
  background: rgba(56, 189, 248, 0.2);
  color: #7dd3fc;
}
.br-select-icon.is-ai {
  background: rgba(168, 85, 247, 0.2);
  color: #d8b4fe;
}

.br-select-model-img {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  object-fit: cover;
  flex-shrink: 0;
}

.br-select-texts {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
  flex: 1;
  gap: 1px;
}

.br-select-title {
  width: 100%;
  font-size: 12.5px;
  line-height: 16px;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}

.br-select-sub {
  width: 100%;
  font-size: 10.5px;
  line-height: 14px;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}

.br-select-chevron {
  color: #94a3b8;
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.br-select-chevron.is-open {
  transform: rotate(180deg);
}

.br-select-menu {
  position: fixed;
  z-index: 999;
  max-height: 240px;
  overflow-y: auto;
  border-radius: 10px;
  background: #0f172a;
  border: 1px solid rgba(245, 158, 11, 0.55);
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.78);
  padding: 5px;
}

.br-select-option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #f8fafc;
  cursor: pointer;
}

.br-select-option:hover,
.br-select-option.is-selected {
  background: rgba(245, 158, 11, 0.16);
}

.br-select-option.is-disabled {
  opacity: 0.38;
  cursor: not-allowed;
  pointer-events: none;
  filter: grayscale(0.7);
}

.br-select-option.is-disabled:hover {
  background: transparent;
}

.br-select-option.is-disabled {
  opacity: 0.42;
  cursor: not-allowed;
  filter: grayscale(0.65);
}

.br-select-option.is-disabled:hover {
  background: transparent;
}

.br-modal-warn-text {
  font-size: 12px;
  font-weight: 700;
  color: #f87171;
  text-align: center;
  padding: 6px 16px;
  background: rgba(239, 68, 68, 0.1);
  border-top: 1px solid rgba(239, 68, 68, 0.25);
}

.br-select-check {
  color: #fde047;
}

.br-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
}

.br-modal-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.br-modal-btn.is-ghost {
  background: transparent;
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #cbd5e1;
}

.br-modal-btn.is-confirm {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
}

.br-agent-badges {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.br-iq-badge {
  display: inline-flex;
  align-items: center;
  padding: 1px 5px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.45);
  color: #7dd3fc;
}

.br-spawn-pill {
  display: inline-flex;
  align-items: center;
  padding: 1px 5px;
  border-radius: 6px;
  font-size: 9.5px;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(16, 185, 129, 0.45);
  color: #6ee7b7;
}

.br-whisper-quote {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10.5px;
  color: #c084fc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-whisper-select {
  height: 30px;
  padding: 0 8px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.9);
  border: 1px solid rgba(192, 132, 252, 0.45);
  color: #e9d5ff;
  font-size: 11.5px;
  font-weight: 600;
  outline: none;
  cursor: pointer;
}

/* Tactical Inline Icons */
.br-iq-icon,
.br-shield-icon,
.br-turn-icon,
.br-trophy-icon,
.br-whisper-icon,
.br-warn-icon,
.br-ap-icon {
  flex-shrink: 0;
  display: inline-block;
  vertical-align: middle;
}

.br-winner-pill,
.br-turn-pill,
.br-storm-pill,
.br-alive-pill,
.br-modal-warn-text {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

